parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "intent": {
      "type": "string",
      "description": "The primary intent of the customer request."
    },
    "category": {
      "type": "string",
      "description": "The category of the customer request."
    },
    "priority": {
      "type": "string",
      "enum": ["low", "medium", "high", "urgent"],
      "description": "The priority of the customer request."
    },
    "requires_customer_data": {
      "type": "boolean",
      "description": "Whether customer-specific data is needed to handle the request."
    },
    "requires_knowledge_search": {
      "type": "boolean",
      "description": "Whether the company knowledge base should be consulted."
    },
    "requires_human": {
      "type": "boolean",
      "description": "Whether human intervention is currently required."
    },
    "summary": {
      "type": "string",
      "description": "A concise summary of the customer's request."
    },
    "additional_information_needed": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Information that is missing and may be required to handle the request."
    }
  },
  "required": [
    "intent",
    "category",
    "priority",
    "requires_customer_data",
    "requires_knowledge_search",
    "requires_human",
    "summary",
    "additional_information_needed"
  ]
}
